//! Product-side service seam. Only trusted Rust bootstrap can construct it;
//! no renderer request selects a profile, connector, or verifier.
use std::{path::{Path,PathBuf},sync::{Arc,Mutex,atomic::Ordering},time::{Duration,Instant}};
use serde_json::{json,Value};
use super::{owned_settings::{OwnedSettings,OwnedSettingsCoordinator},service_context::ServiceContext};
pub fn original_windows_profile(home:&Path,dev:bool)->Result<PathBuf,String>{if !home.is_absolute(){return Err("Trusted home path must be absolute".into())}Ok(home.join(if dev{".csdm-dev"}else{".csdm"}))}
fn authorized_database(expected:&serde_json::Value,requested:&serde_json::Value)->bool{expected.is_object() && expected==requested}
type Connect= dyn Fn()->Result<postgres::Client,String>+Send+Sync;
type Verify= dyn Fn(&mut postgres::Client)->Result<(),String>+Send+Sync;
/// The construction caller is trusted bootstrap, not an IPC payload. Every
/// connection must pass the injected verifier before use.
pub struct TrustedDatabase{identity:Value,connect:Arc<Connect>,verify:Arc<Verify>}
impl TrustedDatabase{
 pub fn from_trusted(identity:Value,connect:impl Fn()->Result<postgres::Client,String>+Send+Sync+'static,verify:impl Fn(&mut postgres::Client)->Result<(),String>+Send+Sync+'static)->Result<Self,String>{if !identity.is_object(){return Err("Trusted database identity must be an object".into())}Ok(Self{identity,connect:Arc::new(connect),verify:Arc::new(verify)})}
 fn connect(&self,requested:&Value)->Result<postgres::Client,String>{if !authorized_database(&self.identity,requested){return Err("Database settings outside trusted authority".into())}let mut client=(self.connect)()?;(self.verify)(&mut client)?;Ok(client)}
}
trait ProductLifecycle:Send+Sync{
 fn quiesce(&self,timeout:Duration)->Result<(),String>;
 fn stop_background(&self,timeout:Duration)->Result<(),String>;
 fn resume(&self,timeout:Duration)->Result<(),String>;
 fn shutdown(&self,timeout:Duration)->Result<(),String>;
 fn settings_updated(&self,event:Value,timeout:Duration)->Result<(),String>;
}
/// This initial product slice cannot start analysis, CLI or background jobs.
/// Both owners are private, so renderer requests cannot introduce such work.
struct SchedulerTransportLifecycle{scheduler:Arc<super::pg79_scheduler::Scheduler>,transport:Mutex<super::live_core::LiveService>,hub:Arc<super::cli_transport::Hub>}
impl ProductLifecycle for SchedulerTransportLifecycle{
 fn quiesce(&self,timeout:Duration)->Result<(),String>{self.scheduler.quiesce(timeout)}
 fn stop_background(&self,_timeout:Duration)->Result<(),String>{Ok(())}
 fn resume(&self,timeout:Duration)->Result<(),String>{self.scheduler.resume(timeout)}
 fn shutdown(&self,timeout:Duration)->Result<(),String>{let deadline=Instant::now()+timeout;self.scheduler.quiesce(remaining(deadline))?;self.scheduler.shutdown(remaining(deadline))?;let mut transport=lock_until(&self.transport,deadline,"product transport")?;transport.shutdown(remaining(deadline))}
 fn settings_updated(&self,event:Value,timeout:Duration)->Result<(),String>{self.hub.queue_settings(event,timeout)}
}
#[derive(Default)]struct Admission{closed:bool,requests:usize}
pub struct ProductService{context:ServiceContext<OwnedSettingsCoordinator<OwnedSettings>,postgres::Client>,database:TrustedDatabase,lifecycle:Arc<dyn ProductLifecycle>,admission:Mutex<Admission>,shutdown_gate:Mutex<()>}
/// The bootstrap must retain an unconfirmed service until cleanup is proven.
pub enum ProductBuild{Ready(ProductService),Unconfirmed{service:ProductService,error:String}}
struct RequestGuard<'a>(&'a Mutex<Admission>);impl Drop for RequestGuard<'_>{fn drop(&mut self){if let Ok(mut state)=self.0.lock(){state.requests-=1}}}
fn lock_until<'a,T>(m:&'a Mutex<T>,deadline:Instant,label:&str)->Result<std::sync::MutexGuard<'a,T>,String>{loop{if Instant::now()>=deadline{return Err(format!("{label} timed out; outcome unconfirmed"))}match m.try_lock(){Ok(g)=>return Ok(g),Err(std::sync::TryLockError::Poisoned(_))=>return Err(format!("{label} poisoned; outcome unconfirmed")),Err(std::sync::TryLockError::WouldBlock)=>std::thread::sleep(Duration::from_millis(5))}}}
fn remaining(deadline:Instant)->Duration{deadline.saturating_duration_since(Instant::now())}
impl ProductService{
 /// No filesystem or database source in renderer payloads is consulted to
 /// construct this service. The caller owns profile and connector authority.
 pub fn from_trusted(profile:&Path,defaults:Value,database:TrustedDatabase,renderer:impl Fn(Value)->Result<(),String>+Send+Sync+'static)->Result<ProductBuild,String>{let settings=Arc::new(OwnedSettingsCoordinator::open_product(profile,defaults)?);settings.load()?;let gate=Arc::new(Mutex::new(()));let state=Arc::new(Mutex::new(super::csdm_analysis::Analyses::new()));let order=Arc::new(Mutex::new(()));let transport=super::live_core::LiveService::with_handler(state.clone(),order.clone(),|_|Err("Product CLI is unavailable".into()),|_,_|Err("Product CLI is unavailable".into()),renderer,|_,_|Err("Product analysis is unavailable".into()))?;let hub=transport.hub.clone();let lifecycle_hub=hub.clone();let read=settings.clone();let read_gate=gate.clone();let scheduler=super::pg79_scheduler::Scheduler::new(state,order,move||{let _guard=read_gate.lock().map_err(|_|"product settings gate poisoned")?;read.load()},|_,_|Err("Product analysis is unavailable".into()),move|event|hub.publish(event));let lifecycle=Arc::new(SchedulerTransportLifecycle{scheduler,transport:Mutex::new(transport),hub:lifecycle_hub});Self::construct(settings,gate,database,lifecycle)}
 fn construct(settings:Arc<OwnedSettingsCoordinator<OwnedSettings>>,gate:Arc<Mutex<()>>,database:TrustedDatabase,lifecycle:Arc<dyn ProductLifecycle>)->Result<ProductBuild,String>{let quiescence=lifecycle.quiesce(Duration::from_secs(2));let service=Self{context:ServiceContext::new(settings,gate,"product connection","product service stopping"),database,lifecycle,admission:Mutex::new(Admission::default()),shutdown_gate:Mutex::new(())};match quiescence{Ok(())=>Ok(ProductBuild::Ready(service)),Err(error)=>{service.admission.lock().map_err(|_|"product admission poisoned")?.closed=true;service.context.stopping.store(true,Ordering::Release);Ok(ProductBuild::Unconfirmed{service,error})}}}
 fn enter(&self)->Result<RequestGuard<'_>,String>{let mut state=self.admission.lock().map_err(|_|"product admission poisoned; outcome unconfirmed")?;if state.closed{return Err("product service stopping".into())}state.requests=state.requests.checked_add(1).ok_or("product request count overflow")?;Ok(RequestGuard(&self.admission))}
 fn settings<T>(&self,work:impl FnOnce(&OwnedSettingsCoordinator<OwnedSettings>)->Result<T,String>)->Result<T,String>{let _guard=lock_until(&self.context.settings_admission,Instant::now()+Duration::from_secs(2),"product settings admission")?;if self.context.stopping.load(Ordering::Acquire){return Err("product service stopping".into())}work(&self.context.settings)}
 pub fn settings_load(&self)->Result<Value,String>{let _request=self.enter()?;self.settings(|s|s.load())}
 pub fn settings_save(&self,value:&Value)->Result<(),String>{let _request=self.enter()?;self.settings(|s|s.save_whole(value))}
 pub fn settings_update(&self,partial:&Value,replace:bool)->Result<Value,String>{let _request=self.enter()?;self.settings(|s|s.update(partial,replace))}
 pub fn connect(&self,payload:Option<Value>)->Result<Value,String>{let _request=self.enter()?;let cfg=match payload{Some(v) if !v.is_null()=>v,_=>self.settings_load()?.get("database").cloned().ok_or("Database settings missing")?};if !authorized_database(&self.database.identity,&cfg){return Err("Database settings outside trusted authority".into())}let owner=self.lifecycle.clone();let background=self.lifecycle.clone();let resume=self.lifecycle.clone();self.context.replace(Duration::from_secs(100),move|t|owner.quiesce(t),move|t|background.stop_background(t),||self.database.connect(&cfg),move|t|resume.resume(t))?;Ok(Value::Null)}
 pub fn disconnect(&self)->Result<Value,String>{let _request=self.enter()?;let owner=self.lifecycle.clone();let background=self.lifecycle.clone();self.context.disconnect(Duration::from_secs(100),move|t|owner.quiesce(t),move|t|background.stop_background(t))?;Ok(Value::Null)}
 fn database_request<T>(&self,work:impl FnOnce(&mut postgres::Client)->Result<T,String>)->Result<T,String>{let deadline=Instant::now()+Duration::from_secs(100);let _admission=lock_until(&self.context.init_admission,deadline,"product request admission")?;if self.context.stopping.load(Ordering::Acquire){return Err("product service stopping".into())}let mut slot=lock_until(&self.context.connection,deadline,"product connection")?;work(slot.as_mut().ok_or("product database disconnected")?)}
 #[cfg(feature="pg80-owned-observe")] pub fn diagnostic_backend_pid(&self)->Result<i32,String>{let _request=self.enter()?;self.database_request(|c|c.query_one("SELECT pg_backend_pid()",&[]).map(|r|r.get(0)).map_err(|e|e.to_string()))}
 #[cfg(feature="pg80-owned-observe")] pub fn diagnostic_inflight(&self)->Result<usize,String>{Ok(self.admission.lock().map_err(|_|"product admission poisoned")?.requests)}
 pub fn dispatch(&self,name:&str,payload:Option<Value>)->Result<Value,String>{let _request=self.enter()?;match name{
  "connect-database"=>self.connect(payload),"disconnect-database"=>self.disconnect(),
  "owned-update-settings"=>{let v=payload.ok_or("Missing settings update")?;let p=v.get("partial").ok_or("Missing settings partial")?;self.settings_update(p,v.get("preserveSourceArray").and_then(Value::as_bool).unwrap_or(false))},
  "fetch-matches-table"=>{let v=payload.unwrap_or(Value::Null);self.database_request(|c|super::csdm_match_readback::fetch_table(c,&v).map(Value::Array))},
  "update-checksums-tags"=>{let v=payload.unwrap_or(Value::Null);let plan=match super::csdm_tags::checksum_plan(&v){Ok(p)=>p,Err(error)=>{eprintln!("Checksum tag request failed: {error}");return Ok(json!({"__demostrikeTagError":1}))}};if let Some(plan)=plan{self.database_request(|c|Ok(match super::csdm_tags::update_checksum_tags(c,plan){Ok(())=>Value::Null,Err(error)=>{eprintln!("Checksum tag update failed; commit outcome may be unknown: {error}");json!({"__demostrikeTagError":1})}}))}else{let deadline=Instant::now()+Duration::from_secs(100);let _gate=lock_until(&self.context.init_admission,deadline,"product checksum admission")?;if self.context.stopping.load(Ordering::Acquire){return Err("product service stopping".into())}Ok(Value::Null)}},
  "update-players-tags"=>{let v=payload.unwrap_or(Value::Null);let plan=match super::csdm_tags::player_plan(&v){Ok(p)=>p,Err(error)=>{eprintln!("Player tag request failed: {error}");return Ok(json!({"__demostrikeTagError":1}))}};if let Some(plan)=plan{self.database_request(|c|Ok(match super::csdm_tags::update_player_tags(c,plan){Ok(())=>Value::Null,Err(error)=>{eprintln!("Player tag update failed; commit outcome may be unknown: {error}");json!({"__demostrikeTagError":1})}}))}else{let deadline=Instant::now()+Duration::from_secs(100);let _gate=lock_until(&self.context.init_admission,deadline,"product player tag admission")?;if self.context.stopping.load(Ordering::Acquire){return Err("product service stopping".into())}Ok(Value::Null)}},
  "delete-tag"=>{let id=payload.as_ref().and_then(Value::as_str).ok_or("Invalid tag ID")?.to_owned();let deadline=Instant::now()+Duration::from_secs(100);self.database_request(|client|{let result=(||{super::csdm_tags::delete(client,&id)?;let _settings=lock_until(&self.context.settings_admission,deadline,"product settings admission")?;let mut value=self.context.settings.load()?;if super::csdm_tags::cleanup_tag_settings(&mut value,&id)?{let snapshot=self.context.settings.update(&value,true)?;self.lifecycle.settings_updated(json!({"name":"settings-updated","payload":snapshot}),remaining(deadline))?;}Ok::<(),String>(())})();Ok(match result{Ok(())=>Value::Null,Err(error)=>{eprintln!("Tag deletion failed after possible database commit: {error}");json!({"__demostrikeTagError":1})}})})},
  "insert-tag"|"update-tag"=>{let v=payload.unwrap_or(Value::Null);self.database_request(|c|Ok(match super::csdm_tags::request(c,&v,name=="update-tag"){Ok(v)=>v,Err(code)=>json!({"__demostrikeTagError":code})}))},
  "supports-original-demos-table"=>Ok(Value::Bool(false)),
  _=>Err(format!("Product request unsupported: {name}")),
 }}
 pub fn shutdown(&self,timeout:Duration)->Result<(),String>{let deadline=Instant::now()+timeout;let _shutdown=lock_until(&self.shutdown_gate,deadline,"product shutdown")?;{let mut state=lock_until(&self.admission,deadline,"product admission")?;state.closed=true;self.context.stopping.store(true,Ordering::Release)}loop{let count=lock_until(&self.admission,deadline,"product admission")?.requests;if count==0{break}if Instant::now()>=deadline{return Err("product requests still active; shutdown unconfirmed".into())}std::thread::sleep(Duration::from_millis(5))}self.lifecycle.shutdown(remaining(deadline))?;let _admission=lock_until(&self.context.init_admission,deadline,"product shutdown admission")?;let _settings=lock_until(&self.context.settings_admission,deadline,"product settings admission")?;*lock_until(&self.context.connection,deadline,"product connection")?=None;Ok(())}
}
#[cfg(test)] mod tests {
 use super::*;
 #[test] fn original_windows_profile_uses_original_home_folders(){let home=Path::new(r"C:\owned-test-home");assert_eq!(original_windows_profile(home,false).unwrap(),home.join(".csdm"));assert_eq!(original_windows_profile(home,true).unwrap(),home.join(".csdm-dev"));}
 #[test] fn trusted_product_profile_uses_original_settings_filename(){let d=tempfile::tempdir().unwrap();let settings=super::super::owned_settings::OwnedSettingsCoordinator::open_product(d.path(),serde_json::json!({"value":1})).unwrap();assert_eq!(settings.load().unwrap()["value"],1);settings.update(&serde_json::json!({"value":2}),false).unwrap();assert!(d.path().join("settings.json").is_file());assert!(!d.path().join("csdm-settings.json").exists());let v:serde_json::Value=serde_json::from_slice(&std::fs::read(d.path().join("settings.json")).unwrap()).unwrap();assert_eq!(v["value"],2);}
 #[test] fn database_request_cannot_override_trusted_authority(){let trusted=serde_json::json!({"hostname":"127.0.0.1","port":46601,"database":"owned_one","username":"owned","password":""});assert!(authorized_database(&trusted,&trusted));let mut spoof=trusted.clone();spoof["database"]=serde_json::json!("other");assert!(!authorized_database(&trusted,&spoof));assert!(!authorized_database(&trusted,&serde_json::Value::Null));}
 #[test] fn separate_real_owners_keep_settings_and_shutdown_isolated(){let a=tempfile::tempdir().unwrap();let b=tempfile::tempdir().unwrap();let one=json!({"database":"one"});let two=json!({"database":"two"});let db=|id:Value|TrustedDatabase::from_trusted(id,||Err("test connector disabled".into()),|_|Ok(())).unwrap();let x=match ProductService::from_trusted(a.path(),json!({"database":one,"value":1}),db(one.clone()),|_|Ok(())).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("unconfirmed construction")};let y=match ProductService::from_trusted(b.path(),json!({"database":two,"value":2}),db(two.clone()),|_|Ok(())).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("unconfirmed construction")};assert_eq!(x.settings_load().unwrap()["value"],1);assert_eq!(y.settings_load().unwrap()["value"],2);x.settings_update(&json!({"value":3}),false).unwrap();assert_eq!(y.settings_load().unwrap()["value"],2);assert!(x.dispatch("not-ported",None).unwrap_err().contains("unsupported"));assert!(x.connect(Some(two)).unwrap_err().contains("authority"));x.shutdown(Duration::from_secs(2)).unwrap();assert!(x.settings_load().is_err());assert_eq!(y.settings_load().unwrap()["value"],2);y.shutdown(Duration::from_secs(2)).unwrap();}
 #[test] fn shutdown_closes_admission_and_waits_for_existing_request(){let dir=tempfile::tempdir().unwrap();let db=TrustedDatabase::from_trusted(json!({"database":"one"}),||Err("disabled".into()),|_|Ok(())).unwrap();let service=Arc::new(match ProductService::from_trusted(dir.path(),json!({"database":{"database":"one"}}),db,|_|Ok(())).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("unconfirmed construction")});let request=service.enter().unwrap();let copy=service.clone();let thread=std::thread::spawn(move||copy.shutdown(Duration::from_secs(2)));let deadline=Instant::now()+Duration::from_secs(1);while !service.admission.lock().unwrap().closed&&Instant::now()<deadline{std::thread::yield_now()}assert!(service.enter().is_err());assert!(!thread.is_finished());drop(request);thread.join().unwrap().unwrap();}
 #[test] fn failed_initial_quiescence_returns_reachable_closed_service(){struct Broken;impl ProductLifecycle for Broken{fn quiesce(&self,_:Duration)->Result<(),String>{Err("not drained".into())}fn stop_background(&self,_:Duration)->Result<(),String>{Ok(())}fn resume(&self,_:Duration)->Result<(),String>{Ok(())}fn shutdown(&self,_:Duration)->Result<(),String>{Ok(())}fn settings_updated(&self,_:Value,_:Duration)->Result<(),String>{Ok(())}}let dir=tempfile::tempdir().unwrap();let db=TrustedDatabase::from_trusted(json!({"database":"one"}),||Err("disabled".into()),|_|Ok(())).unwrap();let settings=Arc::new(OwnedSettingsCoordinator::open_product(dir.path(),json!({"database":{"database":"one"}})).unwrap());let build=ProductService::construct(settings,Arc::new(Mutex::new(())),db,Arc::new(Broken)).unwrap();let ProductBuild::Unconfirmed{service,error}=build else{panic!("failure must retain service")};assert_eq!(error,"not drained");assert!(service.settings_load().is_err());service.shutdown(Duration::from_secs(1)).unwrap();}
 #[test] fn pg97_checksum_route_preserves_noop_and_invalid_contract(){let d=tempfile::tempdir().unwrap();let id=json!({"database":"owned"});let db=TrustedDatabase::from_trusted(id.clone(),||Err("connector must not run".into()),|_|Ok(())).unwrap();let service=match ProductService::from_trusted(d.path(),json!({"database":id}),db,|_|Ok(())).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("service unconfirmed")};assert_eq!(service.dispatch("update-checksums-tags",Some(json!({"tagIds":[]}))).unwrap(),Value::Null);assert_eq!(service.dispatch("update-checksums-tags",Some(json!({"checksums":[],"tagIds":["1"]}))).unwrap(),json!({"__demostrikeTagError":1}));assert!(service.dispatch("update-checksums-tags",Some(json!({"checksums":["a"],"tagIds":["1"]}))).unwrap_err().contains("disconnected"));service.shutdown(Duration::from_secs(2)).unwrap();assert!(service.dispatch("update-checksums-tags",Some(json!({"tagIds":[]}))).is_err());}
 #[test] fn pg102_delete_route_checks_payload_and_connection_before_side_effects(){let d=tempfile::tempdir().unwrap();let id=json!({"database":"owned"});let db=TrustedDatabase::from_trusted(id.clone(),||Err("connector disabled".into()),|_|Ok(())).unwrap();let events=Arc::new(Mutex::new(Vec::new()));let out=events.clone();let service=match ProductService::from_trusted(d.path(),json!({"database":id,"demos":{"tagIds":["3"]},"matches":{"tagIds":[]},"playerProfile":{"tagIds":[]}}),db,move|event|{out.lock().unwrap().push(event);Ok(())}).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("service unconfirmed")};assert!(service.dispatch("delete-tag",Some(json!(3))).unwrap_err().contains("Invalid tag ID"));assert!(service.dispatch("delete-tag",Some(json!("3"))).unwrap_err().contains("disconnected"));assert_eq!(service.settings_load().unwrap()["demos"]["tagIds"],json!(["3"]));assert!(events.lock().unwrap().is_empty());service.shutdown(Duration::from_secs(2)).unwrap();}

 #[test] fn pg103_reentrant_settings_callback_times_out_then_quiesces(){let d=tempfile::tempdir().unwrap();let id=json!({"database":"owned"});let db=TrustedDatabase::from_trusted(id.clone(),||Err("disabled".into()),|_|Ok(())).unwrap();let weak=Arc::new(Mutex::new(std::sync::Weak::<ProductService>::new()));let captured=weak.clone();let (started_tx,started_rx)=std::sync::mpsc::sync_channel(1);let (finished_tx,finished_rx)=std::sync::mpsc::sync_channel(1);let service=Arc::new(match ProductService::from_trusted(d.path(),json!({"database":id}),db,move|_|{started_tx.send(()).unwrap();let result=captured.lock().unwrap().upgrade().unwrap().settings_load().map(|_|());finished_tx.send(()).unwrap();result}).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("service unconfirmed")});*weak.lock().unwrap()=Arc::downgrade(&service);let held=service.context.settings_admission.lock().unwrap();let copy=service.clone();let thread=std::thread::spawn(move||copy.lifecycle.settings_updated(json!({"name":"settings-updated"}),Duration::from_millis(80)));started_rx.recv_timeout(Duration::from_secs(1)).unwrap();assert!(thread.join().unwrap().unwrap_err().contains("unconfirmed"));drop(held);finished_rx.recv_timeout(Duration::from_secs(1)).unwrap();service.shutdown(Duration::from_secs(3)).unwrap();}

 #[test] fn pg107_players_route_noop_and_error_contract(){let d=tempfile::tempdir().unwrap();let id=json!({"database":"owned"});let db=TrustedDatabase::from_trusted(id.clone(),||Err("connector disabled".into()),|_|Ok(())).unwrap();let service=match ProductService::from_trusted(d.path(),json!({"database":id}),db,|_|Ok(())).unwrap(){ProductBuild::Ready(v)=>v,_=>panic!("service unconfirmed")};assert_eq!(service.dispatch("update-players-tags",Some(json!({"tagIds":[]}))).unwrap(),Value::Null);assert!(service.dispatch("update-players-tags",Some(json!({"steamIds":[],"tagIds":["1"]}))).unwrap_err().contains("disconnected"));assert!(service.dispatch("update-players-tags",Some(json!({"steamIds":["s1"],"tagIds":["1"]}))).unwrap_err().contains("disconnected"));service.shutdown(Duration::from_secs(2)).unwrap();}

}
